        className: "language-java",
        children: "public final class LimitedBytesSubscriber implements BodySubscriber<byte[]> {\n    private final CompletableFuture<byte[]> result = new CompletableFuture<>();\n    private final int maxBytes;\n    private final ByteArrayOutputStream out;\n    private Flow.Subscription subscription;\n    private int total;\n\n    public LimitedBytesSubscriber(int maxBytes) {\n        this.maxBytes = maxBytes;\n        this.out = new ByteArrayOutputStream(Math.min(maxBytes, 8192));\n    }\n\n    @Override\n    public CompletionStage<byte[]> getBody() {\n        return result;\n    }\n\n    @Override\n    public void onSubscribe(Flow.Subscription subscription) {\n        this.subscription = subscription;\n        subscription.request(1);\n    }\n\n    @Override\n    public void onNext(List<ByteBuffer> items) {\n        try {\n            for (ByteBuffer buffer : items) {\n                int remaining = buffer.remaining();\n                int allowed = maxBytes - total;\n                if (allowed <= 0) {\n                    subscription.cancel();\n                    result.complete(out.toByteArray());\n                    return;\n                }\n\n                int toRead = Math.min(remaining, allowed);\n                byte[] chunk = new byte[toRead];\n                buffer.get(chunk);\n                out.write(chunk);\n                total += toRead;\n\n                if (remaining > toRead) {\n                    subscription.cancel();\n                    result.complete(out.toByteArray());\n                    return;\n                }\n            }\n            subscription.request(1);\n        } catch (Throwable t) {\n            subscription.cancel();\n            result.completeExceptionally(t);\n        }\n    }\n\n    @Override\n    public void onError(Throwable throwable) {\n        result.completeExceptionally(throwable);\n    }\n\n    @Override\n    public void onComplete() {\n        result.complete(out.toByteArray());\n    }\n}\n"
